BEGIN;
CREATE TABLE nearyou.private_tester_activation_baselines(sha256 text PRIMARY KEY CHECK(sha256~'^[a-f0-9]{64}$'),release_id text NOT NULL CHECK(release_id~'^rel_[A-Za-z0-9_-]{8,100}$'),dark_gates jsonb NOT NULL CHECK(dark_gates='{"nearfamily":false,"nearstory":false,"scheduler":false}'::jsonb));
CREATE TABLE nearyou.private_tester_activation_state(product text PRIMARY KEY CHECK(product IN('nearstory','nearfamily')),version bigint NOT NULL DEFAULT 1,terminal_kill boolean NOT NULL DEFAULT false,release_id text,promoted_baseline_sha256 text REFERENCES nearyou.private_tester_activation_baselines(sha256),evidence_digest text REFERENCES nearyou.release_evidence_audit(claims_digest),updated_at timestamptz NOT NULL DEFAULT statement_timestamp());
CREATE TABLE nearyou.private_tester_activation_invites(product text NOT NULL REFERENCES nearyou.private_tester_activation_state(product),household_hash text NOT NULL CHECK(household_hash~'^[a-f0-9]{64}$'),release_id text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,PRIMARY KEY(product,household_hash,release_id));
CREATE TABLE nearyou.private_tester_activation_audit(operation_id text PRIMARY KEY CHECK(operation_id~'^[a-z][a-z0-9-]{7,127}$'),request_digest text NOT NULL,request_payload jsonb NOT NULL,product text NOT NULL,principal text NOT NULL,action text NOT NULL,prior_version bigint NOT NULL,new_version bigint NOT NULL,release_id text,evidence_digest text,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT statement_timestamp());
INSERT INTO nearyou.private_tester_activation_state(product) VALUES('nearstory'),('nearfamily');
ALTER TABLE nearyou.private_tester_activation_baselines OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.private_tester_activation_state OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.private_tester_activation_invites OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.private_tester_activation_audit OWNER TO nearyou_release_policy_owner;
REVOKE ALL ON nearyou.private_tester_activation_baselines,nearyou.private_tester_activation_state,nearyou.private_tester_activation_invites,nearyou.private_tester_activation_audit FROM PUBLIC,nearyou_app,nearyou_release_verifier,nearyou_rollout_controller,nearyou_private_tester_baseline_verifier;
GRANT USAGE ON SCHEMA nearyou TO nearyou_rollout_controller;
ALTER TABLE nearyou.private_tester_activation_baselines ENABLE ROW LEVEL SECURITY; ALTER TABLE nearyou.private_tester_activation_baselines FORCE ROW LEVEL SECURITY;
ALTER TABLE nearyou.private_tester_activation_state ENABLE ROW LEVEL SECURITY; ALTER TABLE nearyou.private_tester_activation_state FORCE ROW LEVEL SECURITY;
ALTER TABLE nearyou.private_tester_activation_invites ENABLE ROW LEVEL SECURITY; ALTER TABLE nearyou.private_tester_activation_invites FORCE ROW LEVEL SECURITY;
ALTER TABLE nearyou.private_tester_activation_audit ENABLE ROW LEVEL SECURITY; ALTER TABLE nearyou.private_tester_activation_audit FORCE ROW LEVEL SECURITY;
CREATE POLICY private_tester_activation_baselines_owner ON nearyou.private_tester_activation_baselines TO nearyou_release_policy_owner USING(true) WITH CHECK(true); CREATE POLICY private_tester_activation_state_owner ON nearyou.private_tester_activation_state TO nearyou_release_policy_owner USING(true) WITH CHECK(true); CREATE POLICY private_tester_activation_invites_owner ON nearyou.private_tester_activation_invites TO nearyou_release_policy_owner USING(true) WITH CHECK(true); CREATE POLICY private_tester_activation_audit_owner ON nearyou.private_tester_activation_audit TO nearyou_release_policy_owner USING(true) WITH CHECK(true);
CREATE FUNCTION nearyou.reject_private_tester_activation_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,nearyou AS $$ BEGIN RAISE EXCEPTION 'private tester activation audit immutable'; END $$; ALTER FUNCTION nearyou.reject_private_tester_activation_audit_mutation() OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.reject_private_tester_activation_audit_mutation() FROM PUBLIC; CREATE TRIGGER private_tester_activation_audit_immutable BEFORE UPDATE OR DELETE ON nearyou.private_tester_activation_audit FOR EACH ROW EXECUTE FUNCTION nearyou.reject_private_tester_activation_audit_mutation();
CREATE FUNCTION nearyou.private_tester_activation_controller_principal() RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE actor text; BEGIN IF NOT pg_has_role(session_user,'nearyou_rollout_controller','USAGE') THEN RAISE EXCEPTION 'private tester activation controller unavailable'; END IF; SELECT principal INTO actor FROM nearyou.rollout_controller_identities WHERE database_user=session_user; IF actor IS NULL OR actor!~'^service:[A-Za-z0-9_-]{3,100}$' THEN RAISE EXCEPTION 'private tester activation controller unavailable'; END IF; RETURN actor; END $$; ALTER FUNCTION nearyou.private_tester_activation_controller_principal() OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.private_tester_activation_controller_principal() FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.private_tester_activation_controller_principal() TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.register_private_tester_activation_baseline(p_sha256 text,p_release_id text,p_dark_gates jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ BEGIN PERFORM nearyou.assert_private_tester_baseline_verifier(); IF p_sha256!~'^[a-f0-9]{64}$' OR p_release_id!~'^rel_[A-Za-z0-9_-]{8,100}$' OR p_dark_gates IS DISTINCT FROM '{"nearfamily":false,"nearstory":false,"scheduler":false}'::jsonb THEN RAISE EXCEPTION 'private tester activation baseline invalid'; END IF; INSERT INTO nearyou.private_tester_activation_baselines(sha256,release_id,dark_gates) VALUES(p_sha256,p_release_id,p_dark_gates) ON CONFLICT(sha256) DO UPDATE SET sha256=EXCLUDED.sha256 WHERE nearyou.private_tester_activation_baselines.release_id=EXCLUDED.release_id AND nearyou.private_tester_activation_baselines.dark_gates=EXCLUDED.dark_gates; IF NOT FOUND THEN RAISE EXCEPTION 'private tester activation baseline replay conflict'; END IF; END $$; ALTER FUNCTION nearyou.register_private_tester_activation_baseline(text,text,jsonb) OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.register_private_tester_activation_baseline(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.register_private_tester_activation_baseline(text,text,jsonb) TO nearyou_private_tester_baseline_verifier;
CREATE FUNCTION nearyou.load_private_tester_activation_baseline(p_sha256 text) RETURNS TABLE(sha256 text,release_id text,dark_gates jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ BEGIN PERFORM nearyou.private_tester_activation_controller_principal(); RETURN QUERY SELECT b.sha256,b.release_id,b.dark_gates FROM nearyou.private_tester_activation_baselines b WHERE b.sha256=p_sha256; END $$; ALTER FUNCTION nearyou.load_private_tester_activation_baseline(text) OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.load_private_tester_activation_baseline(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.load_private_tester_activation_baseline(text) TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.load_private_tester_activation_evidence(p_digest text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE claims jsonb; BEGIN PERFORM nearyou.private_tester_activation_controller_principal(); SELECT claims_projection INTO claims FROM nearyou.release_evidence_audit WHERE claims_digest=p_digest; RETURN claims; END $$; ALTER FUNCTION nearyou.load_private_tester_activation_evidence(text) OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.load_private_tester_activation_evidence(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.load_private_tester_activation_evidence(text) TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.apply_private_tester_activation(p_principal text,p_operation_id text,p_product text,p_expected_version bigint,p_action text,p_baseline_sha256 text,p_evidence_digest text,p_release_id text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE s nearyou.private_tester_activation_state%ROWTYPE; prior jsonb; request_digest text; canonical_claims text; result jsonb; next_version bigint; actor text; now_ms bigint:=floor(extract(epoch FROM statement_timestamp())*1000)::bigint; BEGIN actor:=nearyou.private_tester_activation_controller_principal(); IF p_principal IS DISTINCT FROM actor OR p_operation_id!~'^[a-z][a-z0-9-]{7,127}$' OR p_product NOT IN('nearstory','nearfamily') OR p_expected_version<1 OR p_action NOT IN('activate','revoke','kill') OR p_baseline_sha256!~'^[a-f0-9]{64}$' OR p_evidence_digest!~'^[a-f0-9]{64}$' OR p_release_id!~'^rel_[A-Za-z0-9_-]{8,100}$' OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR jsonb_typeof(p_payload->'canonicalClaims') IS DISTINCT FROM 'string' OR jsonb_typeof(p_payload->'invites') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'private tester activation invalid'; END IF; canonical_claims:=p_payload->>'canonicalClaims'; IF encode(nearyou_crypto.digest(convert_to(canonical_claims,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_evidence_digest THEN RAISE EXCEPTION 'private tester activation evidence invalid'; END IF; request_digest:=encode(nearyou_crypto.digest(convert_to(jsonb_build_object('action',p_action,'baseline',p_baseline_sha256,'evidence',p_evidence_digest,'operation',p_operation_id,'payload',p_payload,'principal',p_principal,'product',p_product,'release',p_release_id,'version',p_expected_version)::text,'UTF8'),'sha256'),'hex'); SELECT result INTO prior FROM nearyou.private_tester_activation_audit WHERE operation_id=p_operation_id; IF prior IS NOT NULL THEN IF (SELECT request_digest FROM nearyou.private_tester_activation_audit WHERE operation_id=p_operation_id) IS DISTINCT FROM request_digest THEN RAISE EXCEPTION 'private tester activation replay conflict'; END IF; RETURN prior; END IF; SELECT * INTO s FROM nearyou.private_tester_activation_state WHERE product=p_product FOR UPDATE; IF NOT FOUND OR s.version<>p_expected_version THEN RAISE EXCEPTION 'private tester activation version conflict'; END IF; IF s.terminal_kill AND p_action='activate' THEN RAISE EXCEPTION 'private tester activation terminal kill'; END IF; next_version:=s.version+1; IF p_action='activate' THEN IF NOT EXISTS(SELECT 1 FROM nearyou.release_evidence_audit e JOIN nearyou.private_tester_activation_baselines b ON b.sha256=p_baseline_sha256 AND b.release_id=p_release_id AND b.dark_gates='{"nearfamily":false,"nearstory":false,"scheduler":false}'::jsonb WHERE e.claims_digest=p_evidence_digest AND e.release_id=p_release_id AND e.claims_projection=(canonical_claims::jsonb) AND (e.claims_projection->>'expiresAt')::bigint>now_ms) THEN RAISE EXCEPTION 'private tester activation evidence invalid'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'invites') value WHERE coalesce(value->>'householdHash','')!~'^[a-f0-9]{64}$' OR coalesce(value->>'expiresAt','')!~'^[0-9]{1,16}$' OR (value->>'expiresAt')::bigint<=now_ms) THEN RAISE EXCEPTION 'private tester activation invite invalid'; END IF; UPDATE nearyou.private_tester_activation_state SET version=next_version,release_id=p_release_id,promoted_baseline_sha256=p_baseline_sha256,evidence_digest=p_evidence_digest,updated_at=statement_timestamp() WHERE product=p_product; DELETE FROM nearyou.private_tester_activation_invites WHERE product=p_product; INSERT INTO nearyou.private_tester_activation_invites(product,household_hash,release_id,expires_at) SELECT p_product,value->>'householdHash',p_release_id,to_timestamp((value->>'expiresAt')::double precision/1000) FROM jsonb_array_elements(p_payload->'invites'); result:=jsonb_build_object('product',p_product,'releaseId',p_release_id,'version',next_version,'globalPercent',0,'status','active'); ELSIF p_action='revoke' THEN IF s.release_id IS NULL OR s.release_id IS DISTINCT FROM p_release_id THEN RAISE EXCEPTION 'private tester activation release conflict'; END IF; UPDATE nearyou.private_tester_activation_invites SET revoked_at=statement_timestamp() WHERE product=p_product AND release_id=p_release_id AND household_hash IN(SELECT value->>'householdHash' FROM jsonb_array_elements(p_payload->'invites')); UPDATE nearyou.private_tester_activation_state SET version=next_version,updated_at=statement_timestamp() WHERE product=p_product; result:=jsonb_build_object('product',p_product,'releaseId',p_release_id,'version',next_version,'globalPercent',0,'status','revoked'); ELSE UPDATE nearyou.private_tester_activation_invites SET revoked_at=statement_timestamp() WHERE product=p_product; UPDATE nearyou.private_tester_activation_state SET version=next_version,terminal_kill=true,updated_at=statement_timestamp() WHERE product=p_product; result:=jsonb_build_object('product',p_product,'releaseId',s.release_id,'version',next_version,'globalPercent',0,'status','killed'); END IF; result:=result||jsonb_build_object('auditDigest',encode(nearyou_crypto.digest(convert_to(request_digest||':'||next_version::text,'UTF8'),'sha256'),'hex')); INSERT INTO nearyou.private_tester_activation_audit(operation_id,request_digest,request_payload,product,principal,action,prior_version,new_version,release_id,evidence_digest,result) VALUES(p_operation_id,request_digest,p_payload,p_product,actor,p_action,s.version,next_version,CASE WHEN p_action='activate' THEN p_release_id ELSE s.release_id END,p_evidence_digest,result); RETURN result; END $$; ALTER FUNCTION nearyou.apply_private_tester_activation(text,text,text,bigint,text,text,text,text,jsonb) OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.apply_private_tester_activation(text,text,text,bigint,text,text,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.apply_private_tester_activation(text,text,text,bigint,text,text,text,text,jsonb) TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.authorize_private_tester_household(p_product text,p_household_hash text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ BEGIN IF p_product NOT IN('nearstory','nearfamily') OR p_household_hash!~'^[a-f0-9]{64}$' THEN RETURN false; END IF; RETURN EXISTS(SELECT 1 FROM nearyou.private_tester_activation_state s JOIN nearyou.private_tester_activation_baselines b ON b.sha256=s.promoted_baseline_sha256 AND b.release_id=s.release_id AND b.dark_gates='{"nearfamily":false,"nearstory":false,"scheduler":false}'::jsonb JOIN nearyou.release_evidence_audit e ON e.claims_digest=s.evidence_digest AND e.release_id=s.release_id JOIN nearyou.private_tester_activation_invites i ON i.product=s.product AND i.release_id=s.release_id WHERE s.product=p_product AND NOT s.terminal_kill AND (e.claims_projection->>'expiresAt')::bigint>floor(extract(epoch FROM statement_timestamp())*1000) AND i.household_hash=p_household_hash AND i.revoked_at IS NULL AND i.expires_at>statement_timestamp()); END $$; ALTER FUNCTION nearyou.authorize_private_tester_household(text,text) OWNER TO nearyou_release_policy_owner; REVOKE ALL ON FUNCTION nearyou.authorize_private_tester_household(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nearyou.authorize_private_tester_household(text,text) TO nearyou_app;
COMMIT;
